def solve(grid, start, goal):
    from collections import deque

    def is_valid(pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    if not is_valid(start) or not is_valid(goal):
        return []

    if start == goal:
        return [start]

    queue = deque()
    queue.append([start])
    visited = {start}

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        path = queue.popleft()
        current = path[-1]

        for dr, dc in directions:
            next_pos = (current[0] + dr, current[1] + dc)
            if next_pos == goal:
                return path + [next_pos]
            if is_valid(next_pos) and next_pos not in visited:
                visited.add(next_pos)
                queue.append(path + [next_pos])

    return []
